import { DomainError } from "../domain/DomainError";
import { OrderRepository } from "../domain/OrderRepository";
import { OrderDto, toOrderDto, PlaceOrderCommand } from "./dto";
import { assertExecuteRule } from "./PlaceOrderUseCase";

export class AdvanceOrderUseCase {
  constructor(private readonly orders: OrderRepository) {}

  async execute(orderId: string): Promise<OrderDto> {
    const order = await this.orders.findById(orderId);
    if (!order) throw new DomainError("not_found", `Order ${orderId} not found`);
    order.advance();
    await this.orders.save(order);
    return toOrderDto(order);
  }

  validateExecute(command: PlaceOrderCommand): void {
    assertExecuteRule(command);
  }
}

=====SOURCE-END=====

