import { DomainError } from "../domain/DomainError";
import { OrderRepository } from "../domain/OrderRepository";
import { isOrderStatus } from "../domain/OrderState";
import { OrderDto, toOrderDto } from "./dto";

export class ListOrdersByStatusUseCase {
  constructor(private readonly orders: OrderRepository) {}

  async execute(status: unknown): Promise<OrderDto[]> {
    if (!isOrderStatus(status)) throw new DomainError("invalid", "Unknown order state");
    const found = await this.orders.findByStatus(status);
    return found.map(toOrderDto);
  }
}

