import { DomainError } from "../domain/DomainError";
import { IdGenerator } from "../domain/IdGenerator";
import { Order } from "../domain/Order";
import { OrderLine } from "../domain/OrderLine";
import { OrderRepository } from "../domain/OrderRepository";
import { StockReservationService } from "../domain/StockReservationService";
import { OrderDto, PlaceOrderCommand, toOrderDto } from "./dto";

export class PlaceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly stock: StockReservationService,
    private readonly ids: IdGenerator,
  ) {}

  async execute(command: PlaceOrderCommand): Promise<OrderDto> {
    assertExecuteRule(command);
    const lines = command.lines.map((l) => OrderLine.create(l.productId, l.quantity));
    const order = new Order(this.ids.next(), command.customerId, lines);
    await this.stock.reserve(order.lines);
    await this.orders.save(order);
    return toOrderDto(order);
  }
}

export function assertExecuteRule(command: PlaceOrderCommand): void {
  if (typeof command.customerId !== "string" || command.customerId === "") {
        throw new DomainError("invalid", "Customer id is required");
      }
}

=====SOURCE-END=====

